do $$
begin
  if not exists (select 1 from public.insights) then
    insert into public.insights
      (slug, title, excerpt, category, reading_minutes, published_at, body,
       seo_title, seo_description, status)
    values
(
    'what-managed-it-actually-covers', 'What managed IT actually covers', 'Managed IT is often sold as a support contract. The useful version is an operating agreement with defined responsibilities, response times and reporting.', 'Managed services', 6,
    '2026-10-12T00:00:00+05:30', '[{"heading":"The difference between support and operation","paragraphs":["Support begins when someone reports a problem. Operation begins before that: monitoring, patching, capacity review, backup verification and change control happen on a schedule, whether or not a user has noticed anything.","The distinction matters because the failures that hurt most are the ones nobody reports. A backup job that has been failing quietly for three weeks is a support ticket when it is discovered and an operational failure that was never checked."]},{"heading":"What should be written down","paragraphs":["A managed IT agreement should name the systems covered, the monitoring in place, the response time per severity, the escalation path, the reporting cadence and the exclusions. If any of those are left to interpretation, the relationship will be managed by expectation rather than by contract."]},{"heading":"How reporting keeps it honest","paragraphs":["Monthly reporting turns the agreement into something checkable: incidents by severity, response against target, patch compliance, backup status and open risks. It also gives the client a basis for deciding whether the service is worth what it costs, which is a healthier conversation than one held only after an outage."]}]'::jsonb, 'What managed IT actually covers', 'The difference between support and operation, what a managed IT agreement should specify, and how reporting keeps the service accountable.',
    'published'
  ),
(
    'three-questions-before-a-cloud-migration', 'Three questions to answer before a cloud migration', 'Most migration problems are decisions that were never made: what moves, what stays, and how you get back.', 'Cloud & datacenter', 7,
    '2026-09-24T00:00:00+05:30', '[{"heading":"What actually has to move","paragraphs":["A workload inventory with dependencies is the starting point. Applications that appear independent often share directory authentication, storage paths or network rules, and those shared dependencies decide the migration order."]},{"heading":"What should stay where it is","paragraphs":["Latency-sensitive systems, very large data sets and workloads with strict data-location requirements frequently run better on dedicated capacity. A migration that moves everything because moving is the goal tends to cost more and perform worse."]},{"heading":"How you get back","paragraphs":["Each phase needs a rollback position: the previous environment kept intact, the data state recorded, and a tested way to return. Without it, the first unexpected failure turns a planned migration into an incident."]}]'::jsonb, 'Three questions before a cloud migration', 'Workload inventory, what should stay on dedicated capacity, and the rollback position every migration phase needs.',
    'published'
  ),
(
    'a-backup-is-not-a-recovery-plan', 'A backup is not a recovery plan', 'Backup jobs report success. Recovery is a different claim, and it is only true once someone has tested it.', 'Infrastructure', 5,
    '2026-08-30T00:00:00+05:30', '[{"heading":"Success is not integrity","paragraphs":["A backup job can complete and still produce something unusable: an application-consistent copy that is not actually consistent, a database dump that omits a log, or a copy stored on the same array as the source."]},{"heading":"The only useful test","paragraphs":["Restore into an isolated environment and record how long it takes and what is missing. That produces two numbers a business can act on: the recovery point, meaning how much data is lost, and the recovery time, meaning how long the system is unavailable."]},{"heading":"What to fix first","paragraphs":["Start with the systems whose loss would stop the business, verify an off-site copy exists, and put a date on the calendar for the next restore test. A plan that has never been executed is a document, not a capability."]}]'::jsonb, 'A backup is not a recovery plan', 'Why backup success does not prove recoverability, and the restore test that produces a recovery point and recovery time.',
    'published'
  );
  end if;
end $$;

do $$
begin
  if not exists (select 1 from public.legal_documents) then
    insert into public.legal_documents
      (slug, title, description, updated_label, intro, sections,
       seo_title, seo_description, status, published_at)
    values
(
    'privacy-policy', 'Privacy Policy', 'How Infeara Technologies collects, uses, stores and protects personal data, and the rights available under India''s DPDP Act 2023.', '5 November 2026', 'This policy explains what personal data Infeara Technologies collects through this website and in the course of business, why we collect it, how long we keep it and the rights you have. It is written to align with the Digital Personal Data Protection Act, 2023 and the rules made under it.',
    '[{"heading":"Who is responsible for your data","paragraphs":["Infeara Technologies, Chennai, Tamil Nadu, India, is the data fiduciary for personal data collected through this website. For data processed on behalf of a client under a services agreement, the client is the data fiduciary and Infeara acts as a data processor.","Data protection enquiries can be sent to contact@infeara.com. If a Data Protection Officer is appointed, their details will be published on this page."]},{"heading":"What we collect","paragraphs":["We collect only what is needed for the purpose at hand. The categories are:"],"bullets":["Enquiry details you submit: name, work email, organisation, telephone number (optional), area of interest and the content of your message.","Technical information generated by your visit: IP address, browser type, requested page, referring page and timestamp, held in server and security logs.","Analytics information, only if you allow analytics: pages viewed, approximate location derived from IP, device and browser type, and interaction events.","Business contact details shared during a commercial relationship, such as names and work contact information of client personnel."]},{"heading":"Why we use it","paragraphs":["We use enquiry details to respond to you, to scope a possible engagement and to keep a record of the conversation. We use technical logs to operate the site securely, diagnose faults and prevent abuse. We use analytics, where permitted, to understand which pages are useful so that we can improve them.","We do not use your data for automated decision-making that produces legal or similarly significant effects, and we do not sell personal data."]},{"heading":"Consent and lawful processing","paragraphs":["Where consent is the basis, we ask for it separately and clearly, and you can withdraw it at any time. Submitting the contact form requires a affirmative confirmation that you understand this policy. Analytics is disabled until you choose to allow it.","Some processing does not rely on consent: responding to a request you initiated, performing a contract, meeting a legal obligation, or protecting the security of our systems. These correspond to the legitimate uses recognised under the DPDP Act."]},{"heading":"Who we share it with","paragraphs":["We share personal data with service providers who process it on our instructions, under contract and only for the purposes described here. These may include website hosting, email delivery, analytics and IT support providers.","Where a provider processes data outside India, we take reasonable steps to ensure the processing remains subject to appropriate contractual protections and applicable law. We may also disclose data where required by law, a court order or a lawful request from a competent authority."]},{"heading":"How long we keep it","paragraphs":["Enquiry records are kept for as long as needed to deal with the enquiry and any resulting relationship, and then for the period required by applicable law or our legitimate record-keeping needs. Analytics data is retained according to the settings of the analytics service.","When data is no longer needed, we delete it or irreversibly anonymise it. Backup copies are retained for the backup cycle and then overwritten."]},{"heading":"How we protect it","paragraphs":["We apply technical and organisational measures proportionate to the data: access control, encryption in transit, patching, logging, backup and recovery, and restrictions on who can access systems. No method of transmission or storage is completely secure, and we do not claim absolute security.","If a personal data breach occurs, we will assess it and notify the Data Protection Board of India and affected individuals where required by law."]},{"heading":"Your rights","paragraphs":["Subject to applicable law, you may request access to your personal data, correction or completion of inaccurate data, erasure, withdrawal of consent, and nomination of another person to exercise your rights in the event of death or incapacity. You may also raise a grievance about our handling of your data.","Send requests to contact@infeara.com with enough information for us to identify you and the data concerned. We may need to verify your identity before acting. We will respond within the period required by law. If you are not satisfied with our response, you may complain to the Data Protection Board of India."]},{"heading":"Children","paragraphs":["This website is intended for business users and is not directed at children. We do not knowingly collect personal data of children. If you believe a child has provided data, contact us and we will delete it."]},{"heading":"Cookies and analytics","paragraphs":["We use local storage to remember your cookie choice and, only with your permission, Google Analytics cookies. The cookie policy explains the categories, the providers and how to change your choice."]},{"heading":"Changes to this policy","paragraphs":["We may update this policy when our practices or the law change. The revision date at the top of the page will change, and material changes will be described on this page. Continued use of the site after an update does not by itself constitute consent to a new processing purpose."]}]'::jsonb, 'Privacy Policy', 'How Infeara Technologies collects, uses, stores and protects personal data, and the rights available under India''s DPDP Act 2023.', 'published', null
  ),
(
    'terms', 'Terms of Use', 'The terms that govern use of the Infeara Technologies website, intellectual property, liability and governing law.', '5 November 2026', 'These terms govern your use of www.infeara.com. By using the site you accept them. They do not replace the terms of any services agreement, which take precedence for the services described on the site.',
    '[{"heading":"Use of the site","paragraphs":["You may use this site for lawful purposes and in a way that does not interfere with its operation or the use of others. You must not attempt to gain unauthorised access, introduce malicious code, scrape the site at a rate that degrades service, or use it to send unlawful or misleading material.","We may suspend or restrict access where we reasonably believe these terms have been breached or where necessary to protect the site or its users."]},{"heading":"Information on the site","paragraphs":["The content describes our services and approach in general terms. It is not a proposal, quotation, warranty or service commitment. Scope, service levels, pricing and deliverables are set only in a written agreement signed by both parties.","We take care to keep the content accurate, but we do not warrant that every page is complete, current or free of error. Case studies and illustrations describe representative patterns unless a named client has approved the detail. Figures and outcomes are published only where we can evidence them."]},{"heading":"No professional advice","paragraphs":["Content on this site, including articles, checklists and guidance, is general information and not legal, regulatory, financial or security advice for your specific circumstances. You should obtain advice from a qualified professional before acting on it."]},{"heading":"Intellectual property","paragraphs":["The site, its design, text, graphics, illustrations and code are owned by or licensed to Infeara Technologies and are protected by applicable intellectual property law. You may view and print pages for your own reference. You may not reproduce, republish or distribute substantial content without written permission, except where the law permits.","Third-party names and marks mentioned on the site belong to their respective owners. Their mention describes technology we work with and does not imply sponsorship, endorsement or partner status unless expressly stated."]},{"heading":"Third-party links","paragraphs":["The site may link to external websites. We do not control those sites and are not responsible for their content, availability or privacy practices. A link is not an endorsement."]},{"heading":"Availability","paragraphs":["We aim to keep the site available but do not guarantee uninterrupted access. We may change, suspend or withdraw any part of the site, including content and features, without notice."]},{"heading":"Limitation of liability","paragraphs":["To the maximum extent permitted by applicable law, Infeara Technologies is not liable for any indirect, incidental, special or consequential loss arising from use of, or inability to use, this site, including loss of data, revenue or business opportunity.","Nothing in these terms excludes liability that cannot lawfully be excluded, including liability for fraud or wilful misconduct. Liability for services delivered under a separate agreement is governed by that agreement."]},{"heading":"Governing law and jurisdiction","paragraphs":["These terms are governed by the laws of India. Subject to any mandatory provision to the contrary, the courts at Chennai, Tamil Nadu have exclusive jurisdiction over disputes arising from use of this site."]},{"heading":"Changes","paragraphs":["We may update these terms from time to time. The revision date at the top of the page will change. Continued use of the site after an update constitutes acceptance of the revised terms to the extent permitted by law."]}]'::jsonb, 'Terms of Use', 'The terms that govern use of the Infeara Technologies website, intellectual property, liability and governing law.', 'published', null
  ),
(
    'cookies', 'Cookie Policy', 'Which cookies and local storage Infeara uses, what analytics is loaded after consent, and how to change or withdraw your choice.', '5 November 2026', 'This policy explains how this website uses cookies and similar browser storage. The site works without optional cookies; analytics is loaded only after you allow it.',
    '[{"heading":"What cookies and local storage are","paragraphs":["Cookies are small files a website stores in your browser. Local storage is a similar browser mechanism that holds data on your device. Both can be used to remember a choice between visits. This site uses local storage for your consent decision and, with permission, cookies for analytics."]},{"heading":"Essential storage","paragraphs":["We store your cookie choice in local storage under the key infeara-consent. It records whether you allowed analytics or chose essential only. This is required to respect your decision and is not used for tracking or advertising. It remains on your device until you clear site data or change your choice.","No advertising, profiling or social media cookies are set by this site."]},{"heading":"Analytics cookies","paragraphs":["If you choose Allow analytics, we load Google Analytics 4 and set cookies used to distinguish users and sessions, including cookies named _ga and _ga_*. These help us understand which pages are used and how visitors arrive. We enable IP anonymisation where the service supports it.","Google LLC is the provider. Data may be processed outside India. Google''s privacy terms apply to its processing. We do not use analytics data to identify individuals or to make automated decisions about them."]},{"heading":"Changing your choice","paragraphs":["You can change or withdraw your choice at any time using the button below. Withdrawing consent stops analytics loading on your next page view and removes our analytics cookies where the browser allows. You can also clear cookies and site data through your browser settings.","If you had already allowed analytics, clearing the choice does not delete any data already sent to the analytics provider. You can use the provider''s opt-out mechanisms in addition to this site''s control."]},{"heading":"Do Not Track","paragraphs":["Browsers offer various tracking preference signals. Because there is no consistent industry standard for honouring them, this site relies on the consent control above rather than on browser signals."]},{"heading":"Changes and contact","paragraphs":["We may update this policy when the cookies we use change or the law requires it. The revision date at the top of the page will change. Questions about cookies or personal data can be sent to contact@infeara.com."]}]'::jsonb, 'Cookie Policy', 'Which cookies and local storage Infeara uses, what analytics is loaded after consent, and how to change or withdraw your choice.', 'published', null
  );
  end if;
end $$;

do $$
begin
  if not exists (select 1 from public.faq_groups) then
    insert into public.faq_groups
      (title, intro, sort_order, items, status, published_at)
    values
(
    'General', 'Who we are and how an engagement begins.', 1, '[{"question":"What does Infeara Technologies do?","answer":"Infeara operates and secures business IT. That covers managed IT services, cybersecurity, infrastructure and cloud engineering, network engineering, IT facility management, turnkey projects and automation. Managed IT is our primary practice."},{"question":"Where is Infeara based?","answer":"The company is based in Chennai, Tamil Nadu, India. Delivery is remote by default, with onsite attendance arranged where physical access is required, such as hardware replacement or structured cabling."},{"question":"Do you work with clients outside Chennai?","answer":"Yes. We serve organisations across India. Remote delivery covers most administration and support; onsite work is planned around the location and the task."},{"question":"How does an engagement start?","answer":"With an assessment of the existing estate. We record what exists, what is documented, what is monitored and where the exposure sits, then propose scope and service levels in writing. No changes are made during the assessment."},{"question":"What size of organisation do you work with?","answer":"Organisations that run business-critical systems and need them supportable, typically with an internal team that is small, overloaded or between hires. The assessment establishes whether the estate fits our operating model."}]'::jsonb, 'published', null
  ),
(
    'Services & support', 'What is included, how support runs and what changes.', 2, '[{"question":"What is included in managed IT services?","answer":"Monitoring of servers, endpoints and network devices, patch management, backup verification, incident handling, administration, reporting and an escalation path. The exact scope, response targets and exclusions are written into the agreement."},{"question":"How is managed IT different from IT outsourcing?","answer":"Managed IT is accountability for an outcome: the provider owns monitoring, response and reporting. Outsourcing supplies people or capacity to work under the client''s direction. The two are often combined but they are different commitments."},{"question":"Do you support the infrastructure we already have?","answer":"Yes. We start by assessing the current estate and then either operate it as it stands or propose specific remediation where a component cannot be supported reliably."},{"question":"Do you provide on-site support?","answer":"Remote support is the default because it resolves most work faster. Onsite attendance is arranged where a task requires physical access, and the visit is recorded against the asset history."},{"question":"Is support available outside business hours?","answer":"Extended and out-of-hours cover can be included in the service schedule. It is stated explicitly rather than assumed, because the response model and cost differ from standard hours."},{"question":"Who owns the documentation and the software you build?","answer":"The client does. As-built records, access registers and operating notes are handed over, and custom software is delivered with source code, deployment instructions and documentation."}]'::jsonb, 'published', null
  ),
(
    'Security & compliance', 'How security work is scoped and what we can evidence.', 3, '[{"question":"What happens during a security incident?","answer":"The response follows an agreed playbook: contain the affected systems, preserve evidence, restore service from a verified source, then document what happened and what changes prevent a repeat. Notification obligations are decided by the client with their legal advisers."},{"question":"Do you run penetration tests?","answer":"We scope and coordinate penetration testing and vulnerability assessment, and we act on the findings. Testing without a remediation plan produces a report rather than a lower risk position."},{"question":"Can you help with DPDP Act compliance?","answer":"We implement the technical and organisational measures that support compliance: access control, logging, retention, backup and recovery, and evidence for audit questions. Legal interpretation and formal compliance advice sit with the client''s counsel."},{"question":"Do you hold ISO 27001 or other certifications?","answer":"We do not display certifications or attestations that are not current and verifiable. If a certification is material to your selection, ask us directly and we will state the position in writing."}]'::jsonb, 'published', null
  ),
(
    'Commercial', 'How work is priced, scoped and ended.', 4, '[{"question":"How is pricing structured?","answer":"Managed services are priced as a recurring fee based on the systems and hours covered. Projects are quoted against a written scope. Both are stated in the proposal, with exclusions listed rather than discovered later."},{"question":"What is the contract length?","answer":"It depends on the service and the transition work involved. The term, notice period and review points are agreed in the contract. We do not publish a standard term because a poor fit on either side should be ended without friction."},{"question":"Can you procure hardware and licences?","answer":"Yes, we specify and coordinate procurement, and we check that what arrives matches the design and carries the expected warranty. The client can also buy directly."},{"question":"What happens if we leave?","answer":"Documentation, access registers and operating records are handed over, and a transition period is agreed. The environment should be supportable by another provider because it was documented, not because we are being generous."}]'::jsonb, 'published', null
  ),
(
    'Working with us', 'What the relationship looks like month to month.', 5, '[{"question":"How is the transition handled?","answer":"The assessment produces the estate record and the risk list. Transition then follows a written plan covering access, monitoring, documentation, backup verification and the point at which operational responsibility transfers."},{"question":"How often will we hear from you?","answer":"Monthly reporting is standard, with a quarterly service review covering trends, risks and the improvement plan. Priority 1 incidents receive updates at agreed intervals until service is restored."},{"question":"Can you work alongside our internal IT team?","answer":"Yes. Internal staff usually keep ownership of strategy and approvals while we provide cover, specialist engineering or out-of-hours capacity. Responsibilities and decision rights are written down before work starts."}]'::jsonb, 'published', null
  );
  end if;
end $$;
